    int fd_flags;
    fd_flags = fcntl(fd, F_GETFL, 0);
    if (fd_flags < 0) {
      return errno;
    }
#if defined(O_NONBLOCK)
    fd_flags |= O_NONBLOCK;
#elif defined(O_NDELAY)
    fd_flags |= O_NDELAY;
#elif defined(O_FNDELAY)
    fd_flags |= O_FNDELAY;
#else
#error "No definition of non-blocking flag found."
#endif /* O_NONBLOCK */
    if (fcntl(fd, F_SETFL, fd_flags) == -1) {
      ret = errno;
    }
  }
#endif /* _WIN32 */
  return ret;
}

